import { Pipe, PipeTransform } from '@angular/core';

@Pipe({ name: 'fileTypeFilter', standalone: true })
export class FileTypeFilterPipe implements PipeTransform {
  transform(files: any[], type: string): any[] {
    if (!files || !type) return [];
    return files.filter(f => f.type?.toLowerCase() === type.toLowerCase());
  }
}
